/* Generated by tools/build_lines.py from picks/g16.txt. Every line is from: NCERT XII (old) Unit 7. Do not edit by hand. */
(function () {
  const R = window.RES;
  R.addLines("g16", "NCERT XII (old) Unit 7", [{"sec": "Occurrence","ids": [205,206],"t": "Group 16 (chalcogens): O, S, Se, Te, Po, Lv.","exc": false,"tab": false,"src": "p15","page": 16,"o": "Oxygen, sulphur, selenium, tellurium, polonium and livermorium constitute Group 16 of the periodic table. This is sometimes known as group of chalcogens."},{"sec": "Occurrence","ids": [207,208],"t": "Most copper minerals contain O or S (hence \"chalcogens\", ore-formers).","exc": false,"tab": false,"src": "p15","page": 16,"o": "The name is derived from the Greek word for brass and points to the association of sulphur and its congeners with copper. Most copper minerals contain either oxygen or sulphur and frequently the other members of the group."},{"sec": "Occurrence","ids": [211],"t": "O is the most abundant element on earth.","exc": false,"tab": false,"src": "p15","page": 17,"o": "Oxygen is the most abundant of all the elements on earth."},{"sec": "Occurrence","ids": [212],"t": "O: 46.6% of the crust by mass; 20.946% of dry air by volume.","exc": false,"tab": false,"src": "p15","page": 17,"o": "Oxygen forms about 46.6% by mass of earth's crust. Dry air contains 20.946% oxygen by volume."},{"sec": "Occurrence","ids": [213],"t": "S: only 0.03–0.1% of the crust.","exc": false,"tab": false,"src": "p15","page": 17,"o": "However, the abundance of sulphur in the earth's crust is only 0.03-0.1%."},{"sec": "Occurrence","ids": [214],"t": "S as sulphates: gypsum CaSO4·2H2O, epsom salt MgSO4·7H2O, baryte BaSO4; as sulphides: galena PbS, zinc blende ZnS, copper pyrites CuFeS2.","exc": false,"tab": false,"src": "p15","page": 17,"o": "Combined sulphur exists primarily as sulphates such as gypsum CaSO4.2H2O, epsom salt MgSO4.7H2O, baryte BaSO4 and sulphides such as galena PbS, zinc blende ZnS, copper pyrites CuFeS2."},{"sec": "Occurrence","ids": [215],"t": "Traces of S as H2S in volcanoes.","exc": false,"tab": false,"src": "p15","page": 17,"o": "Traces of sulphur occur as hydrogen sulphide in volcanoes."},{"sec": "Occurrence","ids": [217],"t": "Se and Te occur as selenides and tellurides in sulphide ores.","exc": false,"tab": false,"src": "p15","page": 17,"o": "Selenium and tellurium are also found as metal selenides and tellurides in sulphide ores."},{"sec": "Occurrence","ids": [218],"t": "Po: decay product in thorium and uranium minerals.","exc": false,"tab": false,"src": "p15","page": 17,"o": "Polonium occurs in nature as a decay product of thorium and uranium minerals."},{"sec": "Occurrence","ids": [219],"t": "Lv: synthetic, radioactive.","exc": false,"tab": false,"src": "p15","page": 17,"o": "Livermorium is a synthetic radioactive element."},{"sec": "Configuration, radii, ionisation and electron gain enthalpy","ids": [223],"t": "ns^2np^4.","exc": false,"tab": false,"src": "p15","page": 17,"o": "The elements of Group16 have six electrons in the outermost shell and have ns^2 np^4 general electronic configuration."},{"sec": "Configuration, radii, ionisation and electron gain enthalpy","ids": [224],"t": "Radii increase down the group.","exc": false,"tab": false,"src": "p15","page": 17,"o": "Due to increase in the number of shells, atomic and ionic radii increase from top to bottom in the group."},{"sec": "Configuration, radii, ionisation and electron gain enthalpy","ids": [225],"t": "**O is exceptionally small.**","exc": true,"tab": false,"src": "p15","page": 17,"o": "The size of oxygen atom is, however, exceptionally small."},{"sec": "Configuration, radii, ionisation and electron gain enthalpy","ids": [226],"t": "Table 7.6: Electron gain enthalpy ∆egH/kJ mol^–1: O –141, S –200, Se –195, Te –190, Po –174. Electronegativity: O 3.50, S 2.58, Se 2.55, Te 2.01, Po 1.76.","exc": false,"tab": true,"src": "p15","page": 17,"o": "Table 7.6: Electron gain enthalpy ∆egH/kJ mol^–1: O –141, S –200, Se –195, Te –190, Po –174. Electronegativity: O 3.50, S 2.58, Se 2.55, Te 2.01, Po 1.76."},{"sec": "Configuration, radii, ionisation and electron gain enthalpy","ids": [227,228],"t": "∆iH decreases down the group.","exc": false,"tab": false,"src": "p15","page": 18,"o": "Ionisation enthalpy decreases down the group. It is due to increase in size."},{"sec": "Configuration, radii, ionisation and electron gain enthalpy","ids": [229,230],"t": "**∆iH of group 16 < group 15** in the same period (group 15 has extra-stable half-filled p).","exc": true,"tab": false,"src": "p15","page": 18,"o": "However, the elements of this group have lower ionisation enthalpy values compared to those of Group15 in the corresponding periods. This is due to the fact that Group 15 elements have extra stable halffilled p orbitals electronic configurations."},{"sec": "Configuration, radii, ionisation and electron gain enthalpy","ids": [231,232],"t": "**∆egH: O less negative than S** (compact O); from S to Po it becomes less negative again.","exc": true,"tab": false,"src": "p15","page": 18,"o": "Because of the compact nature of oxygen atom, it has less negative electron gain enthalpy than sulphur. However, from sulphur onwards the value again becomes less negative upto polonium."},{"sec": "Configuration, radii, ionisation and electron gain enthalpy","ids": [233],"t": "O has the second-highest EN (after F).","exc": false,"tab": false,"src": "p15","page": 18,"o": "Next to fluorine, oxygen has the highest electronegativity value amongst the elements."},{"sec": "Configuration, radii, ionisation and electron gain enthalpy","ids": [234,235],"t": "EN decreases down the group; metallic character increases O → Po.","exc": false,"tab": false,"src": "p15","page": 18,"o": "Within the group, electronegativity decreases with an increase in atomic number. This implies that the metallic character increases from oxygen to polonium."},{"sec": "Physical properties","ids": [237],"t": "O, S non-metals; Se, Te metalloids; Po metal (radioactive, t½ 13.8 days).","exc": false,"tab": false,"src": "p15","page": 18,"o": "Oxygen and sulphur are non-metals, selenium and tellurium metalloids, whereas polonium is a metal. Polonium is radioactive and is short lived (Half-life 13.8 days)."},{"sec": "Physical properties","ids": [238],"t": "All show allotropy.","exc": false,"tab": false,"src": "p15","page": 18,"o": "All these elements exhibit allotropy."},{"sec": "Physical properties","ids": [239],"t": "m.p. and b.p. increase down the group.","exc": false,"tab": false,"src": "p15","page": 18,"o": "The melting and boiling points increase with an increase in atomic number down the group."},{"sec": "Physical properties","ids": [240],"t": "Big m.p./b.p. gap between O and S: O2 is diatomic, sulphur is S8.","exc": false,"tab": false,"src": "p15","page": 18,"o": "The large difference between the melting and boiling points of oxygen and sulphur may be explained on the basis of their atomicity; oxygen exists as diatomic molecule (O2) whereas sulphur exists as polyatomic molecule (S8)."},{"sec": "Oxidation states","ids": [225],"t": "**O is +2 in OF2 and +1 in O2F2.**","exc": true,"tab": false,"src": "p15","page": 17,"o": "Oxygen shows oxidation states of +2 and +1 in oxygen fluorides OF2 and O2F2 respectively."},{"sec": "Oxidation states","ids": [242,243],"t": "–2 stability decreases down the group; **Po hardly shows –2**.","exc": true,"tab": false,"src": "p15","page": 18,"o": "The stability of -2 oxidation state decreases down the group. Polonium hardly shows –2 oxidation state."},{"sec": "Oxidation states","ids": [244],"t": "O shows only –2 (high EN), except +2 in OF2.","exc": true,"tab": false,"src": "p15","page": 18,"o": "Since electronegativity of oxygen is very high, it shows only negative oxidation state as –2 except in the case of OF2 where its oxidation state is + 2."},{"sec": "Oxidation states","ids": [245],"t": "Others show +2, +4, +6; +4 and +6 more common.","exc": false,"tab": false,"src": "p15","page": 18,"o": "Other elements of the group exhibit + 2, + 4, + 6 oxidation states but + 4 and + 6 are more common."},{"sec": "Oxidation states","ids": [246],"t": "S, Se, Te: usually +4 with oxygen, +6 with fluorine.","exc": false,"tab": false,"src": "p15","page": 18,"o": "Sulphur, selenium and tellurium usually show + 4 oxidation state in their compounds with oxygen and + 6 with fluorine."},{"sec": "Oxidation states","ids": [247],"t": "+6 stability decreases and +4 increases down the group (inert pair).","exc": false,"tab": false,"src": "p15","page": 18,"o": "The stability of + 6 oxidation state decreases down the group and stability of + 4 oxidation state increases (inert pair effect)."},{"sec": "Oxidation states","ids": [248],"t": "Bonding in +4 and +6 is mainly covalent.","exc": false,"tab": false,"src": "p15","page": 18,"o": "Bonding in +4 and +6 oxidation states is primarily covalent."},{"sec": "Anomalous behaviour of oxygen","ids": [249],"t": "O is anomalous: small size, high EN.","exc": true,"tab": false,"src": "p15","page": 18,"o": "The anomalous behaviour of oxygen, like other members of p-block present in second period is due to its small size and high electronegativity."},{"sec": "Anomalous behaviour of oxygen","ids": [250],"t": "Strong H-bonding in H2O, absent in H2S.","exc": true,"tab": false,"src": "p15","page": 18,"o": "One typical example of effects of small size and high electronegativity is the presence of strong hydrogen bonding in H2O which is not found in H2S."},{"sec": "Anomalous behaviour of oxygen","ids": [269],"t": "**O: no d orbitals, so covalency ≤ 4, and rarely exceeds 2 in practice.**","exc": true,"tab": false,"src": "p15","page": 19,"o": "The absence of d orbitals in oxygen limits its covalency to four and in practice, rarely exceeds two."},{"sec": "Anomalous behaviour of oxygen","ids": [270],"t": "Others can expand covalence beyond 4.","exc": false,"tab": false,"src": "p15","page": 19,"o": "On the other hand, in case of other elements of the group, the valence shells can be expanded and covalence exceeds four."},{"sec": "Hydrides H2E","ids": [271],"t": "All form H2E (E = O, S, Se, Te, Po).","exc": false,"tab": false,"src": "p15","page": 19,"o": "All the elements of Group 16 form hydrides of the type H2E (E = O, S, Se, Te, Po)."},{"sec": "Hydrides H2E","ids": [273],"t": "**Acidity increases H2O → H2Te** (H–E bond enthalpy decreases).","exc": false,"tab": false,"src": "p15","page": 19,"o": "Their acidic character increases from H2O to H2Te. The increase in acidic character can be explained in terms of decrease in bond enthalpy for the dissociation of H–E bond down the group."},{"sec": "Hydrides H2E","ids": [274],"t": "Thermal stability decreases H2O → H2Po.","exc": false,"tab": false,"src": "p15","page": 19,"o": "Owing to the decrease in enthalpy for the dissociation of H–E bond down the group, the thermal stability of hydrides also decreases from H2O to H2Po."},{"sec": "Hydrides H2E","ids": [274],"t": "**All hydrides except H2O are reducing**; increasing H2S → H2Te.","exc": true,"tab": false,"src": "p15","page": 19,"o": "All the hydrides except water possess reducing property and this character increases from H2S to H2Te."},{"sec": "Hydrides H2E","ids": [274],"t": "Table 7.7: HEH angle (°) H2O 104, H2S 92, H2Se 91, H2Te 90. b.p/K H2O 373, H2S 213, H2Se 232, H2Te 269. ∆dissH(H–E)/kJ mol^–1 463, 347, 276, 238.","exc": false,"tab": true,"src": "p15","page": 19,"o": "Table 7.7: HEH angle (°) H2O 104, H2S 92, H2Se 91, H2Te 90. b.p/K H2O 373, H2S 213, H2Se 232, H2Te 269. ∆dissH(H–E)/kJ mol^–1 463, 347, 276, 238."},{"sec": "Hydrides H2E","ids": [286],"t": "Acidity increases down the group (E–H bond enthalpy falls).","exc": false,"tab": true,"src": "p15","page": 20,"o": "Due to the decrease in bond (E–H) dissociation enthalpy down the group, acidic character increases."},{"sec": "Hydrides H2E","ids": [701],"t": "Water is liquid because of extensive H-bonding (small, electronegative O).","exc": false,"tab": true,"src": "p15","page": 45,"o": "Because of small size and high electronegativity of oxygen, molecules of water are highly associated through hydrogen bonding resulting in its liquid state."},{"sec": "Oxides EO2, EO3","ids": [253],"t": "Oxides EO2 and EO3 (E = S, Se, Te, Po). O3 and SO2 are gases; SeO2 is solid.","exc": false,"tab": false,"src": "p15","page": 19,"o": "All these elements form oxides of the EO2 and EO3 types where E = S, Se, Te or Po. Ozone (O3) and sulphur dioxide (SO2) are gases while selenium dioxide (SeO2) is solid."},{"sec": "Oxides EO2, EO3","ids": [254],"t": "**Reducing power falls SO2 → TeO2: SO2 is a reductant, TeO2 an oxidant.**","exc": true,"tab": false,"src": "p15","page": 19,"o": "Reducing property of dioxide decreases from SO2 to TeO2; SO2 is reducing while TeO2 is an oxidising agent."},{"sec": "Oxides EO2, EO3","ids": [255,256],"t": "S, Se, Te also form EO3 (SO3, SeO3, TeO3). Both EO2 and EO3 are acidic.","exc": false,"tab": false,"src": "p15","page": 19,"o": "Besides EO2 type, sulphur, selenium and tellurium also form EO3 type oxides (SO3, SeO3, TeO3). Both types of oxides are acidic in nature."},{"sec": "Halides","ids": [257],"t": "Halides EX6, EX4, EX2.","exc": false,"tab": false,"src": "p15","page": 19,"o": "Elements of Group 16 form a large number of halides of the type, EX6, EX4 and EX2 where E is an element of the group and X is a halogen."},{"sec": "Halides","ids": [258],"t": "Halide stability: F^– > Cl^– > Br^– > I^–.","exc": false,"tab": false,"src": "p15","page": 19,"o": "The stability of the halides decreases in the order F^– > Cl^– > Br^– > I^–."},{"sec": "Halides","ids": [259,260,261],"t": "Only hexafluorides are stable hexahalides; all gaseous, octahedral.","exc": false,"tab": false,"src": "p15","page": 19,"o": "Amongst hexahalides, hexafluorides are the only stable halides. All hexafluorides are gaseous in nature. They have octahedral structure."},{"sec": "Halides","ids": [262],"t": "**SF6 is exceptionally stable (steric reasons).**","exc": true,"tab": false,"src": "p15","page": 19,"o": "Sulphur hexafluoride, SF6 is exceptionally stable for steric reasons."},{"sec": "Halides","ids": [263],"t": "SF4 gas, SeF4 liquid, TeF4 solid.","exc": false,"tab": false,"src": "p15","page": 19,"o": "Amongst tetrafluorides, SF4 is a gas, SeF4 a liquid and TeF4 a solid."},{"sec": "Halides","ids": [264,265],"t": "EF4: sp^3d, trigonal bipyramidal with a lone pair at an equatorial position: **see-saw**.","exc": false,"tab": false,"src": "p15","page": 19,"o": "These fluorides have sp^3d hybridisation and thus, have trigonal bipyramidal structures in which one of the equatorial positions is occupied by a lone pair of electrons. This geometry is also regarded as see-saw geometry."},{"sec": "Halides","ids": [266],"t": "**All except O form dichlorides and dibromides.**","exc": true,"tab": false,"src": "p15","page": 19,"o": "All elements except oxygen form dichlorides and dibromides."},{"sec": "Halides","ids": [267],"t": "EX2: sp^3, tetrahedral (electron arrangement).","exc": false,"tab": false,"src": "p15","page": 19,"o": "These dihalides are formed by sp^3 hybridisation and thus, have tetrahedral structure."},{"sec": "Halides","ids": [268,275],"t": "Monohalides are dimeric: S2F2, S2Cl2, S2Br2, Se2Cl2, Se2Br2.","exc": false,"tab": false,"src": "p15","page": 19,"o": "The well known monohalides are dimeric in nature. Examples are S2F2, S2Cl2, S2Br2, Se2Cl2 and Se2Br2."},{"sec": "Halides","ids": [276],"t": "They disproportionate: 2Se2Cl2 → SeCl4 + 3Se","exc": false,"tab": false,"src": "p15","page": 20,"o": "These dimeric halides undergo disproportionation as given below: 2Se2Cl2 → SeCl4 + 3Se"},{"sec": "Dioxygen","ids": [276],"t": "Lab O2: heat chlorates, nitrates, permanganates.","exc": false,"tab": false,"src": "p15","page": 20,"o": "Dioxygen can be obtained in the laboratory by the following ways: (i) By heating oxygen containing salts such as chlorates, nitrates and permanganates."},{"sec": "Dioxygen","ids": [277],"t": "2KClO3 → 2KCl + 3O2 (heat, MnO2)","exc": false,"tab": true,"src": "p15","page": 20,"o": "2KClO3 → 2KCl + 3O2 (heat, MnO2)"},{"sec": "Dioxygen","ids": [277],"t": "Heat oxides of metals low in the electrochemical series, and higher oxides: 2Ag2O → 4Ag + O2; 2Pb3O4 → 6PbO + O2; 2HgO → 2Hg + O2; 2PbO2 → 2PbO + O2","exc": false,"tab": false,"src": "p15","page": 20,"o": "(ii) By the thermal decomposition of the oxides of metals low in the electrochemical series and higher oxides of some metals. 2Ag2O(s) → 4Ag(s) + O2(g); 2Pb3O4(s) → 6PbO(s) + O2(g); 2HgO(s) → 2Hg(l) + O2(g); 2PbO2(s) → 2PbO(s) + O2(g)"},{"sec": "Dioxygen","ids": [277],"t": "2H2O2(aq) → 2H2O(l) + O2(g) (finely divided metals or MnO2 catalyst)","exc": false,"tab": false,"src": "p15","page": 20,"o": "(iii) Hydrogen peroxide is readily decomposed into water and dioxygen by catalysts such as finely divided metals and manganese dioxide. 2H2O2(aq) → 2H2O(l) + O2(g)"},{"sec": "Dioxygen","ids": [278],"t": "Electrolysis of water: H2 at cathode, O2 at anode.","exc": false,"tab": false,"src": "p15","page": 20,"o": "Electrolysis of water leads to the release of hydrogen at the cathode and oxygen at the anode."},{"sec": "Dioxygen","ids": [279],"t": "Industrial: remove CO2 and water vapour from air, liquefy, fractionally distil.","exc": false,"tab": false,"src": "p15","page": 20,"o": "Industrially, dioxygen is obtained from air by first removing carbon dioxide and water vapour and then, the remaining gases are liquefied and fractionally distilled to give dinitrogen and dioxygen."},{"sec": "Dioxygen","ids": [280],"t": "O2: colourless, odourless.","exc": false,"tab": false,"src": "p15","page": 20,"o": "Dioxygen is a colourless and odourless gas."},{"sec": "Dioxygen","ids": [281],"t": "Solubility 3.08 cm^3 per 100 cm^3 water (293 K), enough for aquatic life.","exc": false,"tab": false,"src": "p15","page": 20,"o": "Its solubility in water is to the extent of 3.08 cm^3 in 100 cm^3 water at 293 K which is just sufficient for the vital support of marine and aquatic life."},{"sec": "Dioxygen","ids": [282],"t": "Liquefies at 90 K, freezes at 55 K.","exc": false,"tab": false,"src": "p15","page": 20,"o": "It liquefies at 90 K and freezes at 55 K."},{"sec": "Dioxygen","ids": [282],"t": "**O2 is paramagnetic despite an even number of electrons.**","exc": true,"tab": false,"src": "p15","page": 20,"o": "Molecular oxygen, O2 is unique in being paramagnetic inspite of having even number of electrons."},{"sec": "Dioxygen","ids": [283],"t": "Reacts directly with nearly all metals and non-metals, **except some metals (Au, Pt) and some noble gases**.","exc": false,"tab": false,"src": "p15","page": 20,"o": "Dioxygen directly reacts with nearly all metals and non-metals except some metals (e.g., Au, Pt) and some noble gases."},{"sec": "Dioxygen","ids": [284],"t": "Reactions are often strongly exothermic, which sustains them.","exc": false,"tab": false,"src": "p15","page": 20,"o": "Its combination with other elements is often strongly exothermic which helps in sustaining the reaction."},{"sec": "Dioxygen","ids": [285,298],"t": "Initial heating needed: high O=O bond dissociation enthalpy (493.4 kJ mol^–1).","exc": false,"tab": false,"src": "p15","page": 20,"o": "However, to initiate the reaction, some external heating is required as bond dissociation enthalpy of oxgyen-oxygen double bond is high (493.4 kJ mol^–1)."},{"sec": "Dioxygen","ids": [299],"t": "Some of the reactions of dioxygen with metals, non-metals and other compounds are given below: 2Ca + O2 → 2CaO; 4Al + 3O2 → 2Al2O3; P4 + 5O2 → P4O10; C + O2 → CO2; 2ZnS + 3O2 → 2ZnO + 2SO2; CH4 + 2O2 → CO2 + 2H2O","exc": false,"tab": false,"src": "p15","page": 21,"o": "Some of the reactions of dioxygen with metals, non-metals and other compounds are given below: 2Ca + O2 → 2CaO; 4Al + 3O2 → 2Al2O3; P4 + 5O2 → P4O10; C + O2 → CO2; 2ZnS + 3O2 → 2ZnO + 2SO2; CH4 + 2O2 → CO2 + 2H2O"},{"sec": "Dioxygen","ids": [299,300],"t": "Catalytic oxidations: 2SO2 + O2 → 2SO3 (V2O5); 4HCl + O2 → 2Cl2 + 2H2O (CuCl2)","exc": false,"tab": false,"src": "p15","page": 21,"o": "Some compounds are catalytically oxidised. For example, 2SO2 + O2 → 2SO3 (V2O5); 4HCl + O2 → 2Cl2 + 2H2O (CuCl2)"},{"sec": "Dioxygen","ids": [300],"t": "O2 uses: respiration, combustion; oxyacetylene welding; metal (steel) manufacture.","exc": false,"tab": false,"src": "p15","page": 21,"o": "In addition to its importance in normal respiration and combustion processes, oxygen is used in oxyacetylene welding, in the manufacture of many metals, particularly steel."},{"sec": "Dioxygen","ids": [301],"t": "O2 cylinders: hospitals, high-altitude flying, mountaineering.","exc": false,"tab": false,"src": "p15","page": 21,"o": "Oxygen cylinders are widely used in hospitals, high altitude flying and in mountaineering."},{"sec": "Dioxygen","ids": [302],"t": "Fuels (e.g. hydrazines) burnt in liquid O2: rocket thrust.","exc": false,"tab": false,"src": "p15","page": 21,"o": "The combustion of fuels, e.g., hydrazines in liquid oxygen, provides tremendous thrust in rockets."},{"sec": "Simple oxides","ids": [287],"t": "Oxide = binary compound of O with another element.","exc": false,"tab": false,"src": "p15","page": 21,"o": "A binary compound of oxygen with another element is called oxide."},{"sec": "Simple oxides","ids": [289,290],"t": "One element may form several oxides of widely varying nature.","exc": false,"tab": false,"src": "p15","page": 21,"o": "In many cases one element forms two or more oxides. The oxides vary widely in their nature and properties."},{"sec": "Simple oxides","ids": [291],"t": "Simple (MgO, Al2O3) or mixed (Pb3O4, Fe3O4).","exc": false,"tab": false,"src": "p15","page": 21,"o": "Oxides can be simple (e.g., MgO, Al2O3) or mixed (Pb3O4, Fe3O4)."},{"sec": "Simple oxides","ids": [292],"t": "Simple oxides: acidic, basic, amphoteric (or neutral).","exc": false,"tab": false,"src": "p15","page": 21,"o": "Simple oxides can be classified on the basis of their acidic, basic or amphoteric character."},{"sec": "Simple oxides","ids": [293],"t": "Acidic oxide gives an acid with water: SO2, Cl2O7, CO2, N2O5.","exc": false,"tab": false,"src": "p15","page": 21,"o": "An oxide that combines with water to give an acid is termed acidic oxide (e.g., SO2, Cl2O7, CO2, N2O5)."},{"sec": "Simple oxides","ids": [294],"t": "SO2 + H2O → H2SO3","exc": false,"tab": false,"src": "p15","page": 21,"o": "For example, SO2 combines with water to give H2SO3, an acid. SO2 + H2O → H2SO3"},{"sec": "Simple oxides","ids": [294],"t": "**Non-metal oxides are acidic, but so are some high-oxidation-state metal oxides: Mn2O7, CrO3, V2O5.**","exc": true,"tab": false,"src": "p15","page": 21,"o": "As a general rule, only non-metal oxides are acidic but oxides of some metals in high oxidation state also have acidic character (e.g., Mn2O7, CrO3, V2O5)."},{"sec": "Simple oxides","ids": [295],"t": "Basic oxides give bases: Na2O, CaO, BaO.","exc": false,"tab": false,"src": "p15","page": 21,"o": "The oxides which give a base with water are known as basic oxides (e.g., Na2O, CaO, BaO)."},{"sec": "Simple oxides","ids": [296,297],"t": "CaO + H2O → Ca(OH)2","exc": false,"tab": false,"src": "p15","page": 21,"o": "For example, CaO combines with water to give Ca(OH)2, a base. CaO + H2O → Ca(OH)2"},{"sec": "Simple oxides","ids": [303],"t": "Metal oxides are generally basic.","exc": false,"tab": false,"src": "p15","page": 22,"o": "In general, metallic oxides are basic."},{"sec": "Simple oxides","ids": [304,305,306],"t": "Amphoteric oxides behave as acidic and basic.","exc": false,"tab": false,"src": "p15","page": 22,"o": "Some metallic oxides exhibit a dual behaviour. They show characteristics of both acidic as well as basic oxides. Such oxides are known as amphoteric oxides."},{"sec": "Simple oxides","ids": [307],"t": "They react with both acids and alkalies.","exc": false,"tab": false,"src": "p15","page": 22,"o": "They react with acids as well as alkalies."},{"sec": "Simple oxides","ids": [308],"t": "e.g. Al2O3.","exc": false,"tab": false,"src": "p15","page": 22,"o": "For example, Al2O3 reacts with acids as well as alkalies."},{"sec": "Simple oxides","ids": [309],"t": "Al2O3(s) + 6HCl(aq) + 9H2O(l) → 2[Al(H2O)6]^3+(aq) + 6Cl^–(aq); Al2O3(s) + 6NaOH(aq) + 3H2O(l) → 2Na3[Al(OH)6](aq)","exc": false,"tab": true,"src": "p15","page": 22,"o": "Al2O3(s) + 6HCl(aq) + 9H2O(l) → 2[Al(H2O)6]^3+(aq) + 6Cl^–(aq); Al2O3(s) + 6NaOH(aq) + 3H2O(l) → 2Na3[Al(OH)6](aq)"},{"sec": "Simple oxides","ids": [309,310,311],"t": "**Neutral oxides: CO, NO, N2O.**","exc": false,"tab": false,"src": "p15","page": 22,"o": "There are some oxides which are neither acidic nor basic. Such oxides are known as neutral oxides. Examples of neutral oxides are CO, NO and N2O."},{"sec": "Ozone","ids": [311,312],"t": "O3 is an allotrope of oxygen, too reactive to persist at sea level.","exc": false,"tab": false,"src": "p15","page": 22,"o": "Ozone is an allotropic form of oxygen. It is too reactive to remain for long in the atmosphere at sea level."},{"sec": "Ozone","ids": [313,314],"t": "Formed from O2 by sunlight at ~20 km; the ozone layer screens UV.","exc": false,"tab": false,"src": "p15","page": 22,"o": "At a height of about 20 kilometres, it is formed from atmospheric oxygen in the presence of sunlight. This ozone layer protects the earth's surface from an excessive concentration of ultraviolet (UV) radiations."},{"sec": "Ozone","ids": [315],"t": "Slow dry O2 through a silent electric discharge gives ~10% O3.","exc": false,"tab": false,"src": "p15","page": 22,"o": "When a slow dry stream of oxygen is passed through a silent electrical discharge, conversion of oxygen to ozone (10%) occurs."},{"sec": "Ozone","ids": [316],"t": "Ozonised oxygen: 3O2 → 2O3; ∆H(298 K) = +142 kJ mol^–1","exc": false,"tab": false,"src": "p15","page": 22,"o": "The product is known as ozonised oxygen. 3O2 → 2O3 ∆H(298 K) = +142 kJ mol^–1"},{"sec": "Ozone","ids": [316],"t": "Endothermic, so a **silent** discharge is used, to avoid decomposing the O3.","exc": false,"tab": false,"src": "p15","page": 22,"o": "Since the formation of ozone from oxygen is an endothermic process, it is necessary to use a silent electrical discharge in its preparation to prevent its decomposition."},{"sec": "Ozone","ids": [317],"t": ">10% O3: battery of ozonisers; pure O3 (b.p. 101.1 K) condensed using liquid O2.","exc": false,"tab": false,"src": "p15","page": 22,"o": "If concentrations of ozone greater than 10 per cent are required, a battery of ozonisers can be used, and pure ozone (b.p. 101.1K) can be condensed in a vessel surrounded by liquid oxygen."},{"sec": "Ozone","ids": [318],"t": "**Pure O3: pale blue gas, dark blue liquid, violet-black solid.**","exc": false,"tab": false,"src": "p15","page": 22,"o": "Pure ozone is a pale blue gas, dark blue liquid and violet-black solid."},{"sec": "Ozone","ids": [319,320],"t": "Characteristic smell; harmless in small amounts; above ~100 ppm causes headache, nausea.","exc": false,"tab": false,"src": "p15","page": 22,"o": "Ozone has a characteristic smell and in small concentrations it is harmless. However, if the concentration rises above about 100 parts per million, breathing becomes uncomfortable resulting in headache and nausea."},{"sec": "Ozone","ids": [321,322],"t": "O3 is thermodynamically unstable: O3 → O2 has ∆H < 0 and ∆S > 0, so a large negative ∆G.","exc": false,"tab": false,"src": "p15","page": 22,"o": "Ozone is thermodynamically unstable with respect to oxygen since its decomposition into oxygen results in the liberation of heat (∆H is negative) and an increase in entropy (∆S is positive). These two effects reinforce each other, resulting in large negative Gibbs energy change (∆G) for its conversion into oxygen."},{"sec": "Ozone","ids": [323],"t": "High concentrations can be dangerously explosive.","exc": false,"tab": false,"src": "p15","page": 22,"o": "It is not really surprising, therefore, high concentrations of ozone can be dangerously explosive."},{"sec": "Ozone","ids": [324],"t": "Powerful oxidant: easily gives nascent O (O3 → O2 + O).","exc": false,"tab": false,"src": "p15","page": 22,"o": "Due to the ease with which it liberates atoms of nascent oxygen (O3 → O2 + O), it acts as a powerful oxidising agent."},{"sec": "Ozone","ids": [325,326],"t": "PbS(s) + 4O3(g) → PbSO4(s) + 4O2(g); 2I^–(aq) + H2O(l) + O3(g) → 2OH^–(aq) + I2(s) + O2(g)","exc": false,"tab": false,"src": "p15","page": 22,"o": "For example, it oxidises lead sulphide to lead sulphate and iodide ions to iodine. PbS(s) + 4O3(g) → PbSO4(s) + 4O2(g); 2I^–(aq) + H2O(l) + O3(g) → 2OH^–(aq) + I2(s) + O2(g)"},{"sec": "Ozone","ids": [326,327],"t": "**Estimating O3**: excess KI buffered at pH 9.2 (borate); the liberated I2 is titrated with standard thiosulphate.","exc": false,"tab": false,"src": "p15","page": 22,"o": "When ozone reacts with an excess of potassium iodide solution buffered with a borate buffer (pH 9.2), iodine is liberated which can be titrated against a standard solution of sodium thiosulphate. This is a quantitative method for estimating O3 gas."},{"sec": "Ozone","ids": [342],"t": "NO (from supersonic jet exhaust) reacts rapidly with O3 and may deplete the ozone layer.","exc": false,"tab": false,"src": "p15","page": 23,"o": "Experiments have shown that nitrogen oxides (particularly nitrogen monoxide) combine very rapidly with ozone and there is, thus, the possibility that nitrogen oxides emitted from the exhaust systems of supersonic jet aeroplanes might be slowly depleting the concentration of the ozone layer in the upper atmosphere."},{"sec": "Ozone","ids": [343],"t": "NO(g) + O3(g) → NO2(g) + O2(g)","exc": false,"tab": false,"src": "p15","page": 23,"o": "NO(g) + O3(g) → NO2(g) + O2(g)"},{"sec": "Ozone","ids": [343],"t": "Freons (aerosols, refrigerants) also threaten the ozone layer.","exc": false,"tab": false,"src": "p15","page": 23,"o": "Another threat to this ozone layer is probably posed by the use of freons which are used in aerosol sprays and as refrigerants."},{"sec": "Ozone","ids": [344],"t": "**O3: angular, both O–O bonds 128 pm, angle ~117°.**","exc": false,"tab": false,"src": "p15","page": 23,"o": "The two oxygen-oxygen bond lengths in the ozone molecule are identical (128 pm) and the molecule is angular as expected with a bond angle of about 117°."},{"sec": "Ozone","ids": [345],"t": "Resonance hybrid of two main forms.","exc": false,"tab": false,"src": "p15","page": 23,"o": "It is a resonance hybrid of two main forms."},{"sec": "Ozone","ids": [346],"t": "O3 uses: germicide, disinfectant, water sterilisation.","exc": false,"tab": false,"src": "p15","page": 23,"o": "It is used as a germicide, disinfectant and for sterilising water."},{"sec": "Ozone","ids": [347],"t": "Bleaching oils, ivory, flour, starch; oxidant in KMnO4 manufacture.","exc": false,"tab": false,"src": "p15","page": 23,"o": "It is also used for bleaching oils, ivory, flour, starch, etc. It acts as an oxidising agent in the manufacture of potassium permanganate."},{"sec": "Sulphur: allotropic forms","ids": [328],"t": "S allotropes: most important are yellow rhombic (α) and monoclinic (β).","exc": false,"tab": false,"src": "p15","page": 23,"o": "Sulphur forms numerous allotropes of which the yellow rhombic (α-sulphur) and monoclinic (β-sulphur) forms are the most important."},{"sec": "Sulphur: allotropic forms","ids": [329],"t": "Rhombic is stable at room temperature; becomes monoclinic above 369 K.","exc": false,"tab": false,"src": "p15","page": 23,"o": "The stable form at room temperature is rhombic sulphur, which transforms to monoclinic sulphur when heated above 369 K."},{"sec": "Sulphur: allotropic forms","ids": [329],"t": "Rhombic S: yellow, m.p. 385.8 K, sp. gr. 2.06.","exc": false,"tab": false,"src": "p15","page": 23,"o": "Rhombic sulphur (α-sulphur): This allotrope is yellow in colour, m.p. 385.8 K and specific gravity 2.06."},{"sec": "Sulphur: allotropic forms","ids": [330],"t": "Rhombic crystals from evaporating roll sulphur in CS2; insoluble in water, somewhat soluble in benzene, alcohol, ether.","exc": false,"tab": false,"src": "p15","page": 23,"o": "Rhombic sulphur crystals are formed on evaporating the solution of roll sulphur in CS2. It is insoluble in water but dissolves to some extent in benzene, alcohol and ether."},{"sec": "Sulphur: allotropic forms","ids": [331],"t": "Readily soluble in CS2.","exc": false,"tab": false,"src": "p15","page": 23,"o": "It is readily soluble in CS2."},{"sec": "Sulphur: allotropic forms","ids": [331,332],"t": "Monoclinic S: m.p. 393 K, sp. gr. 1.98; soluble in CS2.","exc": false,"tab": false,"src": "p15","page": 23,"o": "Monoclinic sulphur (β-sulphur): Its m.p. is 393 K and specific gravity 1.98. It is soluble in CS2."},{"sec": "Sulphur: allotropic forms","ids": [332,333,334],"t": "Monoclinic S: melt rhombic S, cool till a crust forms, pierce, pour out the liquid; colourless needles of β-S remain.","exc": false,"tab": false,"src": "p15","page": 23,"o": "This form of sulphur is prepared by melting rhombic sulphur in a dish and cooling, till crust is formed. Two holes are made in the crust and the remaining liquid poured out. On removing the crust, colourless needle shaped crystals of β-sulphur are formed."},{"sec": "Sulphur: allotropic forms","ids": [335,336],"t": "β-S stable above 369 K, α-S below.","exc": false,"tab": false,"src": "p15","page": 23,"o": "It is stable above 369 K and transforms into α-sulphur below it. Conversely, α-sulphur is stable below 369 K and transforms into β-sulphur above this."},{"sec": "Sulphur: allotropic forms","ids": [337,338],"t": "**369 K = transition temperature** (both forms stable).","exc": false,"tab": false,"src": "p15","page": 23,"o": "At 369 K both the forms are stable. This temperature is called transition temperature."},{"sec": "Sulphur: allotropic forms","ids": [339,340],"t": "Both contain S8 molecules, packed differently.","exc": false,"tab": false,"src": "p15","page": 23,"o": "Both rhombic and monoclinic sulphur have S8 molecules. These S8 molecules are packed to give different crystal structures."},{"sec": "Sulphur: allotropic forms","ids": [341],"t": "S8 ring is puckered, crown-shaped.","exc": false,"tab": false,"src": "p15","page": 23,"o": "The S8 ring in both the forms is puckered and has a crown shape."},{"sec": "Sulphur: allotropic forms","ids": [349],"t": "**S2 vapour is paramagnetic**: two unpaired electrons in π* (like O2).","exc": true,"tab": false,"src": "p15","page": 24,"o": "In vapour state sulphur partly exists as S2 molecule which has two unpaired electrons in the antibonding π* orbitals like O2 and, hence, exhibits paramagnetism."},{"sec": "Sulphur: allotropic forms","ids": [350],"t": "Rings of 6–20 S atoms have been synthesised.","exc": false,"tab": false,"src": "p15","page": 24,"o": "Several other modifications of sulphur containing 6-20 sulphur atoms per ring have been synthesised in the last two decades."},{"sec": "Sulphur: allotropic forms","ids": [351],"t": "Cyclo-S6: chair form.","exc": false,"tab": false,"src": "p15","page": 24,"o": "In cyclo-S6, the ring adopts the chair form."},{"sec": "Sulphur: allotropic forms","ids": [352],"t": "At ~1000 K, S2 dominates (paramagnetic).","exc": true,"tab": false,"src": "p15","page": 24,"o": "At elevated temperatures (~1000 K), S2 is the dominant species and is paramagnetic like O2."},{"sec": "Sulphur dioxide","ids": [352],"t": "S burnt in air or O2 gives SO2 with a little (6–8%) SO3. S + O2 → SO2","exc": false,"tab": false,"src": "p15","page": 24,"o": "Sulphur dioxide is formed together with a little (6-8%) sulphur trioxide when sulphur is burnt in air or oxygen: S(s) + O2(g) → SO2(g)"},{"sec": "Sulphur dioxide","ids": [352,353],"t": "Lab: sulphite + dilute H2SO4: SO3^2- + 2H^+ → H2O + SO2","exc": false,"tab": false,"src": "p15","page": 24,"o": "In the laboratory it is readily generated by treating a sulphite with dilute sulphuric acid. SO3^2-(aq) + 2H^+(aq) → H2O(l) + SO2(g)"},{"sec": "Sulphur dioxide","ids": [353],"t": "Industrial: by-product of roasting sulphide ores.","exc": false,"tab": false,"src": "p15","page": 24,"o": "Industrially, it is produced as a by-product of the roasting of sulphide ores."},{"sec": "Sulphur dioxide","ids": [354],"t": "4FeS2(s) + 11O2(g) → 2Fe2O3(s) + 8SO2(g)","exc": false,"tab": true,"src": "p15","page": 24,"o": "4FeS2(s) + 11O2(g) → 2Fe2O3(s) + 8SO2(g)"},{"sec": "Sulphur dioxide","ids": [354],"t": "Dried, liquefied under pressure, stored in steel cylinders.","exc": false,"tab": false,"src": "p15","page": 24,"o": "The gas after drying is liquefied under pressure and stored in steel cylinders."},{"sec": "Sulphur dioxide","ids": [355],"t": "SO2: colourless, pungent, very soluble in water.","exc": false,"tab": false,"src": "p15","page": 24,"o": "Sulphur dioxide is a colourless gas with pungent smell and is highly soluble in water."},{"sec": "Sulphur dioxide","ids": [356],"t": "Liquefies at room temperature under 2 atm; b.p. 263 K.","exc": false,"tab": false,"src": "p15","page": 24,"o": "It liquefies at room temperature under a pressure of two atmospheres and boils at 263 K."},{"sec": "Sulphur dioxide","ids": [356,357],"t": "SO2(g) + H2O(l) ⇌ H2SO3(aq)","exc": false,"tab": false,"src": "p15","page": 24,"o": "Sulphur dioxide, when passed through water, forms a solution of sulphurous acid. SO2(g) + H2O(l) ⇌ H2SO3(aq)"},{"sec": "Sulphur dioxide","ids": [357],"t": "2NaOH + SO2 → Na2SO3 + H2O; Na2SO3 + H2O + SO2 → 2NaHSO3","exc": false,"tab": false,"src": "p15","page": 24,"o": "It reacts readily with sodium hydroxide solution, forming sodium sulphite, which then reacts with more sulphur dioxide to form sodium hydrogen sulphite. 2NaOH + SO2 → Na2SO3 + H2O; Na2SO3 + H2O + SO2 → 2NaHSO3"},{"sec": "Sulphur dioxide","ids": [357],"t": "With water and alkalies SO2 behaves like CO2.","exc": false,"tab": false,"src": "p15","page": 24,"o": "In its reaction with water and alkalies, the behaviour of sulphur dioxide is very similar to that of carbon dioxide."},{"sec": "Sulphur dioxide","ids": [361,362],"t": "SO2(g) + Cl2(g) → SO2Cl2(l) (charcoal catalyst)","exc": false,"tab": false,"src": "p15","page": 25,"o": "Sulphur dioxide reacts with chlorine in the presence of charcoal (which acts as a catalyst) to give sulphuryl chloride, SO2Cl2. SO2(g) + Cl2(g) → SO2Cl2(l)"},{"sec": "Sulphur dioxide","ids": [362],"t": "2SO2(g) + O2(g) → 2SO3(g) (V2O5)","exc": false,"tab": false,"src": "p15","page": 25,"o": "It is oxidised to sulphur trioxide by oxygen in the presence of vanadium(V) oxide catalyst. 2SO2(g) + O2(g) → 2SO3(g) (V2O5)"},{"sec": "Sulphur dioxide","ids": [362,363],"t": "Moist SO2 is a reductant: Fe^3+ → Fe^2+; **decolourises acidified KMnO4 (test for SO2)**.","exc": false,"tab": false,"src": "p15","page": 25,"o": "When moist, sulphur dioxide behaves as a reducing agent. For example, it converts iron(III) ions to iron(II) ions and decolourises acidified potassium permanganate(VII) solution; the latter reaction is a convenient test for the gas."},{"sec": "Sulphur dioxide","ids": [363],"t": "2Fe^3+ + SO2 + 2H2O → 2Fe^2+ + SO4^2– + 4H^+; 5SO2 + 2MnO4^– + 2H2O → 5SO4^2– + 4H^+ + 2Mn^2+","exc": false,"tab": true,"src": "p15","page": 25,"o": "2Fe^3+ + SO2 + 2H2O → 2Fe^2+ + SO4^2– + 4H^+; 5SO2 + 2MnO4^– + 2H2O → 5SO4^2– + 4H^+ + 2Mn^2+"},{"sec": "Sulphur dioxide","ids": [363,364],"t": "SO2 is angular; resonance hybrid of two forms.","exc": false,"tab": false,"src": "p15","page": 25,"o": "The molecule of SO2 is angular. It is a resonance hybrid of the two canonical forms."},{"sec": "Sulphur dioxide","ids": [364],"t": "SO2 uses: refining petroleum and sugar; bleaching wool and silk; antichlor, disinfectant, preservative.","exc": false,"tab": false,"src": "p15","page": 25,"o": "Sulphur dioxide is used (i) in refining petroleum and sugar (ii) in bleaching wool and silk and (iii) as an anti-chlor, disinfectant and preservative."},{"sec": "Sulphur dioxide","ids": [365],"t": "Used to make H2SO4, NaHSO3, Ca(HSO3)2.","exc": false,"tab": false,"src": "p15","page": 25,"o": "Sulphuric acid, sodium hydrogen sulphite and calcium hydrogen sulphite (industrial chemicals) are manufactured from sulphur dioxide."},{"sec": "Sulphur dioxide","ids": [366],"t": "Liquid SO2: solvent for many organic and inorganic chemicals.","exc": false,"tab": false,"src": "p15","page": 25,"o": "Liquid SO2 is used as a solvent to dissolve a number of organic and inorganic chemicals."},{"sec": "Sulphur dioxide","ids": [701],"t": "Both S–O bonds in SO2 are equal (resonance).","exc": false,"tab": true,"src": "p15","page": 45,"o": "Both the S–O bonds are covalent and have equal strength due to resonating structures."},{"sec": "Oxoacids of sulphur","ids": [358],"t": "S oxoacids: H2SO3, H2S2O3, H2S2O4, H2S2O5, H2SxO6 (x = 2–5), H2SO4, H2S2O7, H2SO5, H2S2O8.","exc": false,"tab": false,"src": "p15","page": 25,"o": "Sulphur forms a number of oxoacids such as H2SO3, H2S2O3, H2S2O4, H2S2O5, H2SxO6 (x = 2 to 5), H2SO4, H2S2O7, H2SO5, H2S2O8."},{"sec": "Oxoacids of sulphur","ids": [359,360],"t": "Several are unstable; known only in solution or as salts.","exc": false,"tab": false,"src": "p15","page": 25,"o": "Some of these acids are unstable and cannot be isolated. They are known in aqueous solution or in the form of their salts."},{"sec": "Sulphuric acid","ids": [369],"t": "**Contact process**: (i) burn S or sulphide ores → SO2; (ii) SO2 + O2 → SO3 (V2O5); (iii) SO3 absorbed in H2SO4 → oleum H2S2O7.","exc": false,"tab": false,"src": "p15","page": 26,"o": "Sulphuric acid is manufactured by the Contact Process which involves three steps: (i) burning of sulphur or sulphide ores in air to generate SO2. (ii) conversion of SO2 to SO3 by the reaction with oxygen in the presence of a catalyst (V2O5), and (iii) absorption of SO3 in H2SO4 to give Oleum (H2S2O7)."},{"sec": "Sulphuric acid","ids": [371],"t": "SO2 is purified (dust, arsenic compounds removed).","exc": false,"tab": false,"src": "p15","page": 26,"o": "The SO2 produced is purified by removing dust and other impurities such as arsenic compounds."},{"sec": "Sulphuric acid","ids": [372],"t": "Key step: catalytic oxidation SO2 → SO3 over V2O5.","exc": false,"tab": false,"src": "p15","page": 26,"o": "The key step in the manufacture of H2SO4 is the catalytic oxidation of SO2 with O2 to give SO3 in the presence of V2O5 (catalyst)."},{"sec": "Sulphuric acid","ids": [373],"t": "2SO2(g) + O2(g) → 2SO3(g) (V2O5); ∆rH = –196.6 kJ mol^–1","exc": false,"tab": true,"src": "p15","page": 26,"o": "2SO2(g) + O2(g) → 2SO3(g) (V2O5); ∆rH = –196.6 kJ mol^–1"},{"sec": "Sulphuric acid","ids": [373,374,375],"t": "Exothermic, reversible, volume decreases: low T and high P favour yield, but T can't be too low (slow rate).","exc": false,"tab": false,"src": "p15","page": 26,"o": "The reaction is exothermic, reversible and the forward reaction leads to a decrease in volume. Therefore, low temperature and high pressure are the favourable conditions for maximum yield. But the temperature should not be very low otherwise rate of reaction will become slow."},{"sec": "Sulphuric acid","ids": [376],"t": "**Operating conditions: 2 bar, 720 K.**","exc": false,"tab": false,"src": "p15","page": 26,"o": "In practice, the plant is operated at a pressure of 2 bar and a temperature of 720 K."},{"sec": "Sulphuric acid","ids": [376,377],"t": "SO3 absorbed in conc. H2SO4 → oleum; dilution gives the desired H2SO4.","exc": false,"tab": false,"src": "p15","page": 26,"o": "The SO3 gas from the catalytic converter is absorbed in concentrated H2SO4 to produce oleum. Dilution of oleum with water gives H2SO4 of the desired concentration."},{"sec": "Sulphuric acid","ids": [378],"t": "SO3 + H2SO4 → H2S2O7 (oleum); steps run simultaneously (continuous process).","exc": false,"tab": false,"src": "p15","page": 26,"o": "In the industry two steps are carried out simultaneously to make the process a continuous one and also to reduce the cost. SO3 + H2SO4 → H2S2O7 (Oleum)"},{"sec": "Sulphuric acid","ids": [378],"t": "Contact-process acid is 96–98% pure.","exc": false,"tab": false,"src": "p15","page": 26,"o": "The sulphuric acid obtained by Contact process is 96-98% pure."},{"sec": "Sulphuric acid","ids": [378],"t": "Fig. 7.7: Arsenic purifier containing gelatinous hydrated ferric oxide.","exc": false,"tab": true,"src": "p15","page": 26,"o": "Fig. 7.7: Arsenic purifier containing gelatinous hydrated ferric oxide."},{"sec": "Sulphuric acid","ids": [381],"t": "H2SO4: colourless, dense, oily; sp. gr. 1.84 (298 K); f.p. 283 K, b.p. 611 K; dissolves in water with much heat.","exc": false,"tab": false,"src": "p15","page": 27,"o": "Sulphuric acid is a colourless, dense, oily liquid with a specific gravity of 1.84 at 298 K. The acid freezes at 283 K and boils at 611 K. It dissolves in water with the evolution of a large quantity of heat."},{"sec": "Sulphuric acid","ids": [382,383],"t": "**Add conc. acid slowly to water with stirring** (never the reverse).","exc": false,"tab": false,"src": "p15","page": 27,"o": "Hence, care must be taken while preparing sulphuric acid solution from concentrated sulphuric acid. The concentrated acid must be added slowly into water with constant stirring."},{"sec": "Sulphuric acid","ids": [384],"t": "Reactions stem from: low volatility, strong acidity, strong affinity for water, oxidising ability.","exc": false,"tab": false,"src": "p15","page": 27,"o": "The chemical reactions of sulphuric acid are as a result of the following characteristics: (a) low volatility (b) strong acidic character (c) strong affinity for water and (d) ability to act as an oxidising agent."},{"sec": "Sulphuric acid","ids": [385,386],"t": "In aqueous solution, sulphuric acid ionises in two steps. H2SO4(aq) + H2O(l) → H3O^+(aq) + HSO4^–(aq); Ka1 = very large (Ka1 > 10). HSO4^–(aq) + H2O(l) → H3O^+(aq) + SO4^2-(aq); Ka2 = 1.2 × 10^–2","exc": false,"tab": false,"src": "p15","page": 27,"o": "In aqueous solution, sulphuric acid ionises in two steps. H2SO4(aq) + H2O(l) → H3O^+(aq) + HSO4^–(aq); Ka1 = very large (Ka1 > 10). HSO4^–(aq) + H2O(l) → H3O^+(aq) + SO4^2-(aq); Ka2 = 1.2 × 10^–2"},{"sec": "Sulphuric acid","ids": [386],"t": "Large Ka1 (>10): H2SO4 is largely dissociated to H^+ and HSO4^–.","exc": false,"tab": false,"src": "p15","page": 27,"o": "The larger value of Ka1 (Ka1 > 10) means that H2SO4 is largely dissociated into H^+ and HSO4^–."},{"sec": "Sulphuric acid","ids": [387],"t": "Larger Ka, stronger acid.","exc": false,"tab": false,"src": "p15","page": 27,"o": "Greater the value of dissociation constant (Ka), the stronger is the acid."},{"sec": "Sulphuric acid","ids": [388],"t": "Two series of salts: normal sulphates (Na2SO4, CuSO4) and acid sulphates (NaHSO4).","exc": false,"tab": false,"src": "p15","page": 27,"o": "The acid forms two series of salts: normal sulphates (such as sodium sulphate and copper sulphate) and acid sulphates (e.g., sodium hydrogen sulphate)."},{"sec": "Sulphuric acid","ids": [389],"t": "Low volatility: makes volatile acids from salts. 2MX + H2SO4 → 2HX + M2SO4 (X = F, Cl, NO3)","exc": false,"tab": false,"src": "p15","page": 27,"o": "Sulphuric acid, because of its low volatility can be used to manufacture more volatile acids from their corresponding salts. 2MX + H2SO4 → 2HX + M2SO4 (X = F, Cl, NO3) (M = Metal)"},{"sec": "Sulphuric acid","ids": [389,390],"t": "Strong dehydrating agent: dries wet gases that don't react with it.","exc": false,"tab": false,"src": "p15","page": 27,"o": "Concentrated sulphuric acid is a strong dehydrating agent. Many wet gases can be dried by passing them through sulphuric acid, provided the gases do not react with the acid."},{"sec": "Sulphuric acid","ids": [391,392],"t": "Chars carbohydrates: C12H22O11 → 12C + 11H2O","exc": false,"tab": false,"src": "p15","page": 27,"o": "Sulphuric acid removes water from organic compounds; it is evident by its charring action on carbohydrates. C12H22O11 → 12C + 11H2O (H2SO4)"},{"sec": "Sulphuric acid","ids": [392,393],"t": "Hot conc. H2SO4 is a moderately strong oxidant, between H3PO4 and HNO3.","exc": false,"tab": false,"src": "p15","page": 27,"o": "Hot concentrated sulphuric acid is a moderately strong oxidising agent. In this respect, it is intermediate between phosphoric and nitric acids."},{"sec": "Sulphuric acid","ids": [394],"t": "Oxidises metals and non-metals, itself reduced to SO2: Cu + 2H2SO4 → CuSO4 + SO2 + 2H2O; S + 2H2SO4 → 3SO2 + 2H2O; C + 2H2SO4 → CO2 + 2SO2 + 2H2O","exc": false,"tab": false,"src": "p15","page": 27,"o": "Both metals and non-metals are oxidised by concentrated sulphuric acid, which is reduced to SO2. Cu + 2H2SO4(conc.) → CuSO4 + SO2 + 2H2O; S + 2H2SO4(conc.) → 3SO2 + 2H2O; C + 2H2SO4(conc.) → CO2 + 2SO2 + 2H2O"},{"sec": "Sulphuric acid","ids": [396],"t": "Main use: fertilisers ((NH4)2SO4, superphosphate).","exc": false,"tab": false,"src": "p15","page": 27,"o": "The bulk of sulphuric acid produced is used in the manufacture of fertilisers (e.g., ammonium sulphate, superphosphate)."},{"sec": "Sulphuric acid","ids": [397],"t": "Other uses: petroleum refining; pigments, paints, dyes; detergents; metallurgy (cleaning before enamelling, electroplating, galvanising); storage batteries; nitrocellulose; lab reagent.","exc": false,"tab": false,"src": "p15","page": 27,"o": "Other uses are in: (a) petroleum refining (b) manufacture of pigments, paints and dyestuff intermediates (c) detergent industry (d) metallurgical applications (e.g., cleansing metals before enameling, electroplating and galvanising (e) storage batteries (f) in the manufacture of nitrocellulose products and (g) as a laboratory reagent."},{"sec": "Sulphuric acid","ids": [417],"t": "CaF2 + H2SO4 → CaSO4 + 2HF","exc": false,"tab": false,"src": "p15","page": 28,"o": "CaF2 + H2SO4 → CaSO4 + 2HF"},{"sec": "Sulphuric acid","ids": [701,702,703],"t": "H2SO4 is very strong because of the first ionisation; HSO4^– → SO4^2– is tiny, so Ka2 << Ka1.","exc": false,"tab": true,"src": "p15","page": 45,"o": "H2SO4 is a very strong acid in water largely because of its first ionisation to H3O^+ and HSO4^–. The ionisation of HSO4^– to H3O^+ and SO4^2– is very very small. That is why Ka2 << Ka1."}]);
})();
